<?php use Hls\Http\View as V; ?><section class="panel"><p>Nomor: <strong><?= V::escape($row['transfer_ref']) ?></strong></p><p>Tanggal: <?= V::escape($row['transfer_date']) ?> · Status: <?= V::escape($row['status']) ?></p><p>Asal: <?= V::escape($row['source_branch'].' / '.$row['source_warehouse'].' - '.$row['source_warehouse_name']) ?></p><p>Tujuan: <?= V::escape($row['destination_branch'].' / '.$row['destination_warehouse'].' - '.$row['destination_warehouse_name']) ?></p><p><?= V::escape((string)$row['note']) ?></p><?php if($row['status']==='DRAFT'&&$access->can('inventory.transfer.send')): ?><form method="post" action="<?= $this->url('/inventory/transfer-send') ?>"><?= $this->csrf() ?><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><button class="button button-primary">Kirim</button></form><?php endif ?><?php if($row['status']==='DRAFT'&&$access->can('inventory.transfer.cancel')): ?><form method="post" action="<?= $this->url('/inventory/transfer-cancel') ?>"><?= $this->csrf() ?><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><button class="button">Batalkan</button></form><?php endif ?><?php if($row['status']==='SENT'&&$access->can('inventory.transfer.receive')): ?><form method="post" action="<?= $this->url('/inventory/transfer-receive') ?>"><?= $this->csrf() ?><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><button class="button button-primary">Terima</button></form><?php endif ?></section><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Barang</th><th>Satuan</th><th>Kuantitas</th></tr></thead><tbody><?php foreach($lines as $l): ?><tr><td><?= V::escape($l['item_code'].' - '.$l['item_name']) ?></td><td><?= V::escape($l['unit_name']) ?></td><td><?= number_format((float)$l['quantity'],3,',','.') ?></td></tr><?php endforeach ?></tbody></table></div></section><a class="button" href="<?= $this->url('/inventory/transfers') ?>">Kembali</a>
